"""Shared static quote form, native Netlify fallback and enquiry information."""
from html import escape


def quote_section(source='home'):
    prefix = 'home-enquiry' if source == 'home' else 'contact-enquiry'
    # Register one canonical definition; the homepage posts the identical schema.
    detection = 'data-netlify="true"' if source == 'contact' else ''
    project_options = ''.join(f'<option value="{escape(value)}">{escape(value)}</option>' for value in ['Driveway','Block paving','Patio','Garden landscaping','Fencing','Not sure yet'])
    return f'''<section class="quote-section" id="quote-section-{source}" aria-labelledby="{prefix}-title"><div class="wrap quote-layout"><div class="quote-intro"><span class="eyebrow">Your project starts here</span><h2 id="{prefix}-title">Tell us your plans.<br>Let’s get the ball rolling.</h2><p>Leave a few details and George can get in touch about your driveway, patio or garden project. You do not need a finished design to start the conversation.</p><ul class="quote-benefits"><li>Free site visits and no-obligation quotes</li><li>Colne, Burnley, Pendle, Barnoldswick &amp; Skipton</li><li>One local team for paving, landscaping and fencing</li></ul><div class="quote-trust"><p>Prefer to speak now? Call <a href="tel:+447581223870">07581 223870</a>.</p><p>You can also email <a href="mailto:george_entwistle@hotmail.co.uk">george_entwistle@hotmail.co.uk</a>.</p></div></div><div class="quote-panel" id="get-a-quote"><span class="eyebrow">Free quote enquiry</span><h3>A few details. A first step.</h3><p>Fields marked * are required. Email and project notes are optional.</p><form class="quote-form" id="{prefix}" name="quote-enquiry" method="POST" action="/thank-you/" {detection} netlify-honeypot="bot-field" data-quote-form data-state="idle" aria-label="Request a free quote"><input type="hidden" name="form-name" value="quote-enquiry"><input type="hidden" name="source-page" value="{source}"><input type="hidden" name="subject" value="New quote enquiry — Entwistle Paving"><p class="form-honeypot" hidden><label>Leave this field empty: <input name="bot-field" tabindex="-1" autocomplete="off"></label></p><div class="form-grid"><div class="form-field"><label for="{prefix}-name">Your name <span class="required" aria-hidden="true">*</span></label><input id="{prefix}-name" name="name" type="text" autocomplete="name" required maxlength="100"></div><div class="form-field"><label for="{prefix}-phone">Phone number <span class="required" aria-hidden="true">*</span></label><input id="{prefix}-phone" name="phone" type="tel" autocomplete="tel" required minlength="6" maxlength="40"></div><div class="form-field"><label for="{prefix}-postcode">Project postcode <span class="required" aria-hidden="true">*</span></label><input id="{prefix}-postcode" name="postcode" type="text" autocomplete="postal-code" required maxlength="12"></div><div class="form-field"><label for="{prefix}-project">What are you planning? <span class="required" aria-hidden="true">*</span></label><select id="{prefix}-project" name="project-type" required><option value="">Please select</option>{project_options}</select></div><div class="form-field wide"><label for="{prefix}-email">Email address <span class="optional">(optional)</span></label><input id="{prefix}-email" name="email" type="email" autocomplete="email" maxlength="254"></div><div class="form-field wide"><label for="{prefix}-message">A little about your project <span class="optional">(optional)</span></label><textarea id="{prefix}-message" name="message" rows="4" maxlength="3000" placeholder="What would you like to change? A rough size or a few ideas can help."></textarea></div></div><div class="form-privacy"><p>We’ll use your details to respond to this enquiry. <a href="/enquiry-privacy/">How we handle your information</a>.</p></div><div class="form-actions"><button class="button" type="submit"><span data-submit-label>Send my enquiry</span><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M4 12h15m-6-6 6 6-6 6"/></svg></button><p>Free site visit.<br>No-obligation quote.</p></div><p class="form-status" data-form-status role="alert" aria-live="assertive" tabindex="-1" hidden></p></form></div></div></section>'''


def thank_you(brand_mark, button):
    return f'''<section class="section"><div class="wrap"><div class="thankyou-card"><div class="thankyou-mark">{brand_mark()}</div><span class="eyebrow">Enquiry received</span><h1>Thanks for getting<br>in touch.</h1><p>Your enquiry has been sent to George Entwistle Driveways &amp; Paving. George can use the details you provided to get in touch about your project.</p><p>If you would like to speak directly, call <a href="tel:+447581223870">07581 223870</a>.</p><div class="actions">{button('Explore our work','/gallery/','outline')}{button('Back to home','/')}</div></div></div></section>'''


def enquiry_privacy():
    return '''<section class="section white"><div class="wrap privacy-copy"><h2>Who handles your enquiry</h2><p>George Entwistle Driveways &amp; Paving is based in Colne, Lancashire. For questions about your enquiry information, email <a href="mailto:george_entwistle@hotmail.co.uk">george_entwistle@hotmail.co.uk</a> or call <a href="tel:+447581223870">07581 223870</a>.</p><h2>What you provide and how it is used</h2><p>The form asks for your name, phone number, project postcode and the type of work you are considering. Your email address and project notes are optional. These details are used to respond to your request, discuss the proposed work, prepare a quotation and arrange a site visit where appropriate.</p><p>This processing supports the steps you ask us to take towards a possible service.</p><h2>Where website enquiries are handled</h2><p>Website forms are processed and stored through Netlify Forms, our website provider. George and the administrators supporting this website can access enquiries for handling your request and maintaining the service. Netlify also processes technical information for operating its service and filtering spam. See <a href="https://www.netlify.com/privacy/" target="_blank" rel="noopener">Netlify’s privacy information</a>.</p><h2>Keeping and managing your details</h2><p>Enquiry information is used while dealing with your request and any resulting work, with related business records kept where needed for that purpose. Contact George to ask about the information held, to correct it or to request its deletion. You can also raise a concern or ask about objecting to further use of your enquiry information.</p><p>If you remain concerned about how personal information is handled, you can contact the <a href="https://ico.org.uk/make-a-complaint/" target="_blank" rel="noopener">Information Commissioner’s Office</a>.</p></div></section>'''
